// DelegationServiceServer is the server API for DelegationService service.
// All implementations must embed UnimplementedDelegationServiceServer
// for forward compatibility.
//
// DelegationService - ADM 代行營運工作階段與稽核服務（delegation 模組）
//
// 全部 RPC 皆為 **internal-only**：唯一合法呼叫方是 Gateway，
// 不對前端暴露、不經任何 public/app namespace。
type DelegationServiceServer interface {
	// 判定某位管理員此刻能否對某店家開始代行，並回傳可用 scope / reason 選項 / TTL。
	// **必須唯讀且可安全重複呼叫**（前端每 30 秒、focus 與每次 create 前都會呼叫）。
	//
	//	不得寫入任何資料、不得產生稽核列、不得消耗冪等額度。
	Preflight(context.Context, *PreflightRequest) (*PreflightResponse, error)
	// 建立短效代行工作階段，回傳 handoff code 與安全摘要；credential 只在兌換時簽發。
	// 冪等鍵為 (actor_admin_id, idempotency_key)；同 key 重放回同一個 session，
	//
	//	並改簽一把新的 handoff code、覆蓋舊 hash。
	CreateSession(context.Context, *CreateSessionRequest) (*CreateSessionResponse, error)
	// 兌換一次性 handoff code，取回該工作階段的 operation credential
	//
	//	（A29／設計書 §4.5「憑證跨 host 傳遞」；Gateway 側是 S6）。
	//
	// **唯一呼叫方是 Gateway 的 S6 端點**，而 S6 既不要 ADM session cookie、
	//
	//	也不要 operation credential —— 授權完全由 handoff code 自己承擔。
	//	⇒ 四道防護全部落在本 RPC 的實作內，一道都不得推給呼叫端。
	//
	// **必須是單句 CAS**：
	//
	//	UPDATE … SET handoff_code_hash = NULL, credential_hash = :new_hash
	//	 WHERE handoff_code_hash = $1 AND handoff_expires_at > now()
	//	   AND status = 'active' AND ended_at IS NULL
	//	   AND now() < expires_at                                  -- session hard 到期
	//	   AND now() < last_active_at + make_interval(secs => $2)  -- session idle 到期
	//	 RETURNING …            （$2 = DELEGATION_SESSION_IDLE_SECONDS）
	//	rows = 0 一律回 9282（DELEGATION_HANDOFF_INVALID，四種成因共用同一個碼）。
	//
	// ⚠️ **述詞恰為六個，最後兩個不可省**：DB 的 status 沒有 expired 值
	//
	//	（到期是讀取時推導，設計書 §7.5.1 順位 2／3）⇒ 一個 hard 或 idle
	//	已到期的 session，status 仍然是 'active'。少了它們，過期工作階段
	//	照樣兌換得出 credential 並回 200，而四道防護的第 ④ 道只做到一半。
	//	handoff 窗口與 session 窗口**互不蘊含**（DELEGATION_HANDOFF_TTL_SECONDS
	//	與 DELEGATION_SESSION_* 之間沒有任何不等式關係，§8.5.1）。
	//	**禁止先 SELECT 再 UPDATE** —— 那是兩個人同時兌換同一把 code 時
	//	各拿到一份 credential 的形狀。
	//
	// 兌換在同一句寫入隨機 credential 的 SHA-256 hash；不寫稽核列、
	//
	//	不順延 last_active_at、不 bump revision —— 兌換不是代行操作。
	RedeemHandoff(context.Context, *RedeemHandoffRequest) (*RedeemHandoffResponse, error)
	// 由 credential 反查當前工作階段摘要。
	// **不得 bump revision、不得延長 expires_at、不得更新 issued_at**——
	//
	//	連續兩次呼叫必須回傳位元等價的摘要，否則前端永遠進不了工作區。
	//
	// **counts_as_activity=false 時完全唯讀**（GET /current 端點恆走這一側，每 30 秒被輪詢）；
	//
	//	counts_as_activity=true 時**只多順延 last_active_at 一欄**（閒置逾時，§6.2.4a／A23），
	//	回應內容不因此改變——last_active_at 不進 DTO、不進九欄對帳。
	GetCurrentSession(context.Context, *GetCurrentSessionRequest) (*GetCurrentSessionResponse, error)
	// 結束工作階段（＝立刻到期）。冪等：已 ended/expired/revoked 仍回成功。
	// credential 查無對應列時也回成功（見設計書 §6.1.5 的理由）。
	EndSession(context.Context, *EndSessionRequest) (*EndSessionResponse, error)
	// 撤銷工作階段（ADM 治理動作，非代行能力）。即時 fail-closed，revision + 1。
	// 已 expired 者仍可撤銷以留下治理痕跡；revoked 為終態。
	RevokeSession(context.Context, *RevokeSessionRequest) (*RevokeSessionResponse, error)
	// ADM 登出連動：撤銷該管理員名下**所有進行中**的代行工作階段（§4.5 auth.go 條目、
	//
	//	§12.4 ① 的等效 SQL）。呼叫端是 Gateway 的登出 handler。
	//
	// **不收 revoke_reason**：本 RPC 的存在本身就決定了它是 'admin_logout'，
	//
	//	由服務端寫入固定字面值。收一個字串參數就是給呼叫端一個寫錯它的機會，
	//	而稽核的四種撤銷來源全靠這一欄機械區分（與 §6.1.15 端點 6 的連帶撤銷同理）。
	//
	// `revoked_by_admin_id` 一律 ＝ actor 自己：登出是他自己的動作，不是第三方介入，
	//
	//	§12.4 ① 正是以「兩者相同」來判讀這一類撤銷。
	//
	// 冪等：述詞是「進行中」，重放一次撤不到任何列，回成功 ＋ 空陣列，
	//
	//	因此不收 idempotency_key。
	RevokeSessionsByActor(context.Context, *RevokeSessionsByActorRequest) (*RevokeSessionsByActorResponse, error)
	// 兩階段稽核的第一階段：在**任何** domain write 之前寫入 PENDING 稽核列。
	// 寫入失敗即 fail-closed，呼叫方不得進行 domain write。
	RecordAuditIntent(context.Context, *RecordAuditIntentRequest) (*RecordAuditIntentResponse, error)
	// 兩階段稽核的第二階段：把 PENDING 更新為 SUCCEEDED / FAILED，
	// 並在同一個交易內寫入 outbox 列（Outbox 保 MQ 必發，§22 例外 2）。
	// 呼叫方必須同步有限重試 3 次（指數退避，總計 < 2 秒）；仍失敗才留 PENDING。
	ConfirmAuditResult(context.Context, *ConfirmAuditResultRequest) (*ConfirmAuditResultResponse, error)
	// 上兩支的批次版，供 §7.2.8 的批次端點使用。
	// **語意完全等同於「呼叫 N 次單筆版」**，差別只在跳數與交易邊界：
	//
	//	仍然寫 N 列稽核、仍然逐項 idempotency_key、仍然逐項回 audit_log_id。
	//	存在的理由是「Gateway 的跳數不得與 items 筆數成正比」（§7.2.8）。
	//
	// RecordAuditIntentBatch 是**逐項成敗**：某一項寫不進去只讓該項以 9279 收尾，
	//
	//	其餘照跑（§7.2.8 讀法 6）。實作必須逐項 SAVEPOINT —— PostgreSQL 交易內
	//	任一句 SQL 失敗即整個交易 aborted（25P02），不設 SAVEPOINT 做不到部分成功。
	RecordAuditIntentBatch(context.Context, *RecordAuditIntentBatchRequest) (*RecordAuditIntentBatchResponse, error)
	// ConfirmAuditResultBatch 相反，是 **all-or-nothing**：N 列 UPDATE 與 N′ 列 outbox
	//
	//	INSERT 在同一個交易內，失敗即 N 列一起停在 PENDING（寬度分析見 §7.3.3 視窗 A）。
	//	重試次數與退避沿用單筆版的裁決，每次的 deadline 與總預算另有參數（§8.5.1 (B)）。
	ConfirmAuditResultBatch(context.Context, *ConfirmAuditResultBatchRequest) (*ConfirmAuditResultBatchResponse, error)
	// 稽核時間線查詢（UI 的「代行紀錄」頁）。唯讀。
	ListAuditLogs(context.Context, *ListAuditLogsRequest) (*ListAuditLogsResponse, error)
	// 結束摘要（UI 的「結束本次代行？」modal）。唯讀。
	// fulfillment_action_count / finance_action_count 結構上恆為 "0"。
	// **兩支 HTTP 端點共用這一支 RPC，差別只在 session_id 從哪裡來**（§6.1.11）：
	//
	//	GET .../{sessionId}/summary  → ADM session 授權，session_id 取自 URL（可查任意工作階段）
	//	GET .../current/summary      → operation credential 授權，session_id 由 Gateway 反查（只回自己那一個）
	//	**不新增第二支 RPC**：兩者的回應形狀與計算規則完全相同，分開會讓「零出貨零財務」有兩個實作。
	GetSessionSummary(context.Context, *GetSessionSummaryRequest) (*GetSessionSummaryResponse, error)
	// ==================== 跨工作階段治理查詢（§11.3 P1） ====================
	// 兩支都是治理回看：ListSessions 答「這段期間誰代行了哪些店」，ListAllAuditLogs
	//
	//	答「這家店／這位操作者跨工作階段做過什麼」。唯讀。
	//
	// 兩者刻意**不帶 actor_admin_id**，與上面兩支查詢 RPC 一致：身分由 Gateway 的
	//
	//	requireAdmin 承擔，這一層不做第二道判定。加一個用不到的 actor 欄位會讓下一個
	//	人以為它是授權閘門，而它不是——真正的閘門在 Gateway。
	//
	// 也刻意**不吃 admin_accounts.delegation_enabled**：那把尺管的是「誰可以發起代行」，
	//
	//	回看已經發生的事是稽核，兩者不同問題。綁在一起會讓稽核角色查不到東西。
	ListSessions(context.Context, *ListSessionsRequest) (*ListSessionsResponse, error)
	ListAllAuditLogs(context.Context, *ListAllAuditLogsRequest) (*ListAllAuditLogsResponse, error)
	// 授權列表（治理總覽）。唯讀。
	// status 只有 ""／effective／ineffective 三值。{active, revoked, expired} 那種分類
	//
	//	會漏掉 effective_from 落在未來的列（維運 SQL 仍可能建），那些列不屬於任何一類
	//	⇒ 篩選時靜默消失。二分是全覆蓋的；畫面要說明「為什麼無效」時讀該列的
	//	revoked_at／effective_until 自己判斷。
	//
	// effective 由伺服端以 now() 逐列評估後放進投影，**前端不得自行從三個時間欄推導**。
	ListDelegationAuthorizations(context.Context, *ListDelegationAuthorizationsRequest) (*ListDelegationAuthorizationsResponse, error)
	// 單店授權詳情（商家詳情頁的「代行授權」面板）。唯讀。
	// 查無授權列**不是錯誤**：回 code=0 ＋ data.exists=false（照 seller.proto 的
	//
	//	GetActiveSellerSuspensionForAdmin「查無即空投影」慣例）。用 9286 表示「尚未開通」
	//	會讓「這家店還沒開通」與「上游掛了」在前端長得一模一樣。
	//
	// ⚠️ **只查 store 級那一列，不得回落全域列**：全域列存在時會遮蔽所有店，治理畫面
	//
	//	若把它當成「這家店的設定」顯示，管理員會對著一列不屬於該店的授權按下撤回。
	//	delegation 模組側要用 store 級專用查詢，**不要沿用工作階段建立路徑那一支**
	//	（那支「不過濾有效性、含全域回落」是刻意的，改它會動到 Preflight 的判定）。
	GetDelegationAuthorization(context.Context, *GetDelegationAuthorizationRequest) (*GetDelegationAuthorizationResponse, error)
	// 開通或重新開通一家店的代行授權。
	// ⚠️ **uq_sda_store 的述詞是 WHERE target_store_id IS NOT NULL，不含 revoked_at
	//
	//	⇒ 每店終生一列**。因此復權只能 UPDATE 同一列，**不得 INSERT 第二列**；本 RPC
	//	同時承載「首建」與「復權」，兩者在維運語意上本來就同義（都是重設
	//	effective_from／approved_at／approved_by_admin_id ＝ 一次全新的授權）。
	//	實際走了哪一條由回應的 outcome 回報，**不由呼叫方以旗標指定**。
	//
	// CAS（單句，rows 數即判定）：
	//
	//	INSERT … ON CONFLICT (target_store_id) WHERE target_store_id IS NOT NULL
	//	  DO UPDATE SET … WHERE seller_delegation_authorizations.revoked_at IS NOT NULL
	//	  RETURNING *
	//	rows = 0 ⇒ 已存在有效授權 → 9285（不是例外、不是重試訊號）。
	//
	// ⚠️ **禁止先 SELECT 再決定 INSERT 或 UPDATE** —— 那是兩個管理員同時開通同一家店時
	//
	//	一個靜默覆蓋另一個的形狀。
	//
	// ⚠️ **也禁止「讓 DB 拋唯一鍵錯再 catch」** —— PostgreSQL 交易內任一句 SQL 失敗即
	//
	//	整個交易 aborted（25P02），catch 得到例外，但後續任何一句 SELECT 都會炸成 500。
	//
	// 授權列的寫入與稽核列的 INSERT **必須同一個交易**：分開就會出現「授權變了但沒有人
	//
	//	知道是誰改的」，而那正是本組 RPC 存在的理由。
	//
	// 不接受 effective_from，一律 now()：未來生效會長出「已建立但尚未生效」的第三態，
	//
	//	preflight／告警／UI 全部要跟著長，而沒有任何營運需求要它（DB 仍保留該能力給維運 SQL）。
	//
	// target_store_id 必填，**不開放由本 RPC 建立全域列**（uq_sda_global 那一列營運上禁建，
	//
	//	Runbook 把它列為「查到就要追查來源」的異常）。
	GrantDelegationAuthorization(context.Context, *GrantDelegationAuthorizationRequest) (*GrantDelegationAuthorizationResponse, error)
	// 調整既有有效授權的範圍／依據／期限。**全量取代，不是 partial update**：
	//
	//	granted_capabilities 送什麼就是什麼，未送的欄位不會沿用舊值。
	//
	// CAS：UPDATE … WHERE target_store_id = $1 AND revoked_at IS NULL RETURNING *
	//
	//	rows = 0 時再以一句唯讀 SELECT 分辨成因：該列不存在 → 9286；已撤回 → 9264。
	//	**不得把兩者合併成同一個模糊錯誤**——前者要引導去「開通」，後者要引導去「復權」。
	//
	// ⚠️ **與 Grant 分開是刻意的，不要合成一支 upsert**：兩者的 CAS 述詞恰好相反
	//
	//	（revoked_at IS NOT NULL vs IS NULL）。合成之後，管理員對著一張過時分頁按下
	//	「調整範圍」，會把一個因故撤回的店**靜默復權**，而且沒有任何錯誤訊號。分開之後
	//	這條路徑在 SQL 層就不可能發生 —— 這也是本組 RPC 不需要 revision 樂觀鎖的理由。
	UpdateDelegationAuthorization(context.Context, *UpdateDelegationAuthorizationRequest) (*UpdateDelegationAuthorizationResponse, error)
	// 撤回一家店的代行授權。
	// CAS：UPDATE … SET revoked_at = now(), revoked_by_admin_id = $2, revoke_reason = $3
	//
	//	    WHERE target_store_id = $1 AND revoked_at IS NULL RETURNING *
	//	rows = 0 且該列存在 ⇒ 早已撤回，回**成功**且 already_revoked = true（照
	//	RevokeSession「對已終態者仍回成功」）；該列不存在才是 9286。
	//
	// ⚠️ **冪等成功不得補寫第二列稽核**：稽核列記的是「發生了什麼」，第二次撤回什麼都
	//
	//	沒發生。同理 revoked_at／revoked_by_admin_id／revoke_reason 一律保留第一次的值。
	//
	// **同一個交易內連帶撤銷該店所有進行中的工作階段**，被撤銷的 id 回在 revoked_session_ids。
	//
	//	理由：Runbook 明定「撤回授權不會中止進行中的工作階段，須另走人工撤銷，兩者都做
	//	才是完整的撤回」——把一個已知會被忘記的人工第二步留到 API 時代，等於交付一個
	//	半殘的治理動作。⚠️ 這一段**必須與授權列同交易**：分開就留下「授權已撤回但代行
	//	還在跑」的窗口，而那正是本欄要消除的東西。
	//	revoked_session_ids 恆為陣列（無工作階段時為空陣列，不是 null）。
	RevokeDelegationAuthorization(context.Context, *RevokeDelegationAuthorizationRequest) (*RevokeDelegationAuthorizationResponse, error)
	// 單店的授權變更歷程（delegation_authorization_audit_logs）。唯讀。
	// 這張表存在的理由：uq_sda_store 每店一列 ⇒ 復權會就地覆蓋前一次撤回的
	//
	//	revoked_at／revoked_by_admin_id／revoke_reason，「這家店曾經被撤回過」在授權列上
	//	不留任何痕跡。手寫 SQL 時代靠「source_reference 指向的依據文件能追溯前一次撤回」
	//	勉強撐住，那是**人的流程保證**；有了介面之後改授權變成一次點擊，該保證失效。
	//
	// ⚠️ append-only：本表沒有任何 UPDATE／DELETE 路徑（連 updated_at 都不設）。
	// 從未開通過的店回 9286，**不是空清單** —— 「查無此店的授權」與「有授權但沒改過」是
	//
	//	兩件事，而後者不可能發生：開通本身就會留下第一列 GRANT。
	ListDelegationAuthorizationHistory(context.Context, *ListDelegationAuthorizationHistoryRequest) (*ListDelegationAuthorizationHistoryResponse, error)
	mustEmbedUnimplementedDelegationServiceServer()
}

